package app.moddedfiles.extension.media;

import android.media.MediaCodec;

import app.moddedfiles.extension.DiagLog;
import app.moddedfiles.extension.ModSettings;

import java.util.ArrayDeque;
import java.util.IdentityHashMap;
import java.util.List;

/** Android-only hooks; all references to bundled Media3 types are generated by the patch. */
public final class MediaHooks {
    private static final String AREA = "media";
    private static String lastFormat;

    private MediaHooks() {}

    public static boolean tryExceedCapabilities() {
        try {
            return ModSettings.getBool(ModSettings.MEDIA_TRY_EXCEED_CAPABILITIES,
                    ModSettings.DEFAULT_MEDIA_TRY_EXCEED_CAPABILITIES);
        } catch (Throwable t) {
            DiagLog.e(AREA, "Reading playback policy failed", t);
            return false;
        }
    }

    public static void attach(Object player) {
        try {
            synchronized (MediaHooks.class) {
                lastFormat = null;
            }
            PlaybackListener.attach(player);
            DiagLog.i(AREA, "Player listener attached; tryExceedCapabilities="
                    + tryExceedCapabilities());
        } catch (Throwable t) {
            DiagLog.e(AREA, "Attaching player listener failed", t);
        }
    }

    public static boolean preserveCapabilityAllowance(Throwable error) {
        try {
            // The bundled ExoPlaybackException uses this stable value only for renderer
            // FORMAT_EXCEEDS_CAPABILITIES errors. Leave Files' other recovery paths intact.
            return tryExceedCapabilities() && error != null && error.getMessage() != null
                    && error.getMessage().contains("format_supported=NO_EXCEEDS_CAPABILITIES");
        } catch (Throwable t) {
            DiagLog.e(AREA, "Checking capability recovery failed", t);
            return false;
        }
    }

    public static synchronized void onFormat(String format) {
        try {
            if (!format.equals(lastFormat)) {
                lastFormat = format;
                DiagLog.i(AREA, "Video input: " + format);
            }
        } catch (Throwable t) {
            DiagLog.e(AREA, "Logging video format failed", t);
        }
    }

    public static void format(Object format) {
        try {
            PlaybackListener.format(format);
        } catch (Throwable t) {
            DiagLog.e(AREA, "Reading video format failed", t);
        }
    }

    public static void onDecoder(String name) {
        try {
            DiagLog.i(AREA, "Video decoder initialized: " + name);
        } catch (Throwable t) {
            DiagLog.e(AREA, "Logging video decoder failed", t);
        }
    }

    /** The value is intentionally unchanged: keep Media3's real capability verdict for errors. */
    public static int rendererSupport(int support) {
        try {
            DiagLog.i(AREA, "Video renderer support=" + (support & 7)
                    + "; capabilitiesExceeded=" + ((support & 7) == 3));
        } catch (Throwable t) {
            DiagLog.e(AREA, "Logging renderer capabilities failed", t);
        }
        return support;
    }

    /** R8 removed the enableDecoderFallback flag, but retained the renderer's retry loop. */
    public static void decoderQueue(ArrayDeque<Object> queue, List<?> candidates) {
        try {
            if (candidates.isEmpty()) return;
            // The patch replaces the original get(0)/add block on a newly created empty queue.
            if (tryExceedCapabilities()) {
                ArrayDeque<Object> replacement = new ArrayDeque<>(candidates);
                queue.addAll(replacement);
                DiagLog.i(AREA, "Decoder fallback enabled; candidates=" + candidates);
            } else {
                queue.add(candidates.get(0));
            }
        } catch (Throwable t) {
            DiagLog.e(AREA, "Enabling decoder fallback failed; retaining original queue", t);
            try {
                queue.clear();
                if (!candidates.isEmpty()) queue.add(candidates.get(0));
            } catch (Throwable restoreError) {
                DiagLog.e(AREA, "Restoring preferred decoder failed", restoreError);
            }
        }
    }

    public static void onCodecError(Throwable error) {
        try {
            logError("Video codec failure (fallback may continue)", error);
        } catch (Throwable t) {
            DiagLog.e(AREA, "Logging codec failure failed", t);
        }
    }

    public static void onPlayerError(Throwable error, int code) {
        try {
            String message = error == null ? "null" : String.valueOf(error.getMessage());
            String exceeded = code == 4004 || message.contains("NO_EXCEEDS_CAPABILITIES")
                    ? "true" : message.contains("format_supported=") ? "false" : "unknown";
            logError("Player error " + errorCodeName(code) + " (" + code
                    + "); capabilitiesExceeded=" + exceeded, error);
        } catch (Throwable t) {
            DiagLog.e(AREA, "Logging player error failed", t);
        }
    }

    public static void bridgeError(Throwable error) {
        try {
            DiagLog.e(AREA, "Media3 listener bridge failed", error);
        } catch (Throwable ignored) {
            // A diagnostic failure must never interrupt playback or error delivery.
        }
    }

    private static void logError(String prefix, Throwable error) {
        StringBuilder text = new StringBuilder(prefix);
        IdentityHashMap<Throwable, Boolean> seen = new IdentityHashMap<>();
        for (Throwable cause = error; cause != null && !seen.containsKey(cause);
                cause = cause.getCause()) {
            seen.put(cause, Boolean.TRUE);
            text.append("\ncaused by ").append(cause.getClass().getName())
                    .append(": ").append(cause.getMessage());
            String message = cause.getMessage();
            if (message != null && (message.startsWith("Decoder init failed: ")
                    || message.startsWith("Decoder failed: "))) {
                int start = message.indexOf(": ") + 2;
                int end = message.indexOf(',', start);
                text.append("; decoderName=")
                        .append(end < 0 ? message.substring(start) : message.substring(start, end));
            }
            // Media3's decoder init / decoder exception messages contain the actual codec name.
            if (cause instanceof MediaCodec.CodecException) {
                text.append("; codecDiagnostic=")
                        .append(((MediaCodec.CodecException) cause).getDiagnosticInfo());
            }
        }
        DiagLog.e(AREA, text.toString(), error);
    }

    // PlaybackException's stable numeric codes; no Media3 library is packaged in the extension.
    private static String errorCodeName(int code) {
        switch (code) {
            case 1000: return "ERROR_CODE_UNSPECIFIED";
            case 1001: return "ERROR_CODE_REMOTE_ERROR";
            case 1002: return "ERROR_CODE_BEHIND_LIVE_WINDOW";
            case 1003: return "ERROR_CODE_TIMEOUT";
            case 1004: return "ERROR_CODE_FAILED_RUNTIME_CHECK";
            case 2000: return "ERROR_CODE_IO_UNSPECIFIED";
            case 2001: return "ERROR_CODE_IO_NETWORK_CONNECTION_FAILED";
            case 2002: return "ERROR_CODE_IO_NETWORK_CONNECTION_TIMEOUT";
            case 2003: return "ERROR_CODE_IO_INVALID_HTTP_CONTENT_TYPE";
            case 2004: return "ERROR_CODE_IO_BAD_HTTP_STATUS";
            case 2005: return "ERROR_CODE_IO_FILE_NOT_FOUND";
            case 2006: return "ERROR_CODE_IO_NO_PERMISSION";
            case 2007: return "ERROR_CODE_IO_CLEARTEXT_NOT_PERMITTED";
            case 2008: return "ERROR_CODE_IO_READ_POSITION_OUT_OF_RANGE";
            case 3001: return "ERROR_CODE_PARSING_CONTAINER_MALFORMED";
            case 3002: return "ERROR_CODE_PARSING_MANIFEST_MALFORMED";
            case 3003: return "ERROR_CODE_PARSING_CONTAINER_UNSUPPORTED";
            case 3004: return "ERROR_CODE_PARSING_MANIFEST_UNSUPPORTED";
            case 4001: return "ERROR_CODE_DECODER_INIT_FAILED";
            case 4002: return "ERROR_CODE_DECODER_QUERY_FAILED";
            case 4003: return "ERROR_CODE_DECODING_FAILED";
            case 4004: return "ERROR_CODE_DECODING_FORMAT_EXCEEDS_CAPABILITIES";
            case 4005: return "ERROR_CODE_DECODING_FORMAT_UNSUPPORTED";
            case 4006: return "ERROR_CODE_DECODING_RESOURCES_RECLAIMED";
            case 5001: return "ERROR_CODE_AUDIO_TRACK_INIT_FAILED";
            case 5002: return "ERROR_CODE_AUDIO_TRACK_WRITE_FAILED";
            case 5003: return "ERROR_CODE_AUDIO_TRACK_OFFLOAD_WRITE_FAILED";
            case 5004: return "ERROR_CODE_AUDIO_TRACK_OFFLOAD_INIT_FAILED";
            case 6000: return "ERROR_CODE_DRM_UNSPECIFIED";
            case 6001: return "ERROR_CODE_DRM_SCHEME_UNSUPPORTED";
            case 6002: return "ERROR_CODE_DRM_PROVISIONING_FAILED";
            case 6003: return "ERROR_CODE_DRM_CONTENT_ERROR";
            case 6004: return "ERROR_CODE_DRM_LICENSE_ACQUISITION_FAILED";
            case 6005: return "ERROR_CODE_DRM_DISALLOWED_OPERATION";
            case 6006: return "ERROR_CODE_DRM_SYSTEM_ERROR";
            case 6007: return "ERROR_CODE_DRM_DEVICE_REVOKED";
            case 6008: return "ERROR_CODE_DRM_LICENSE_EXPIRED";
            case 7000: return "ERROR_CODE_VIDEO_FRAME_PROCESSOR_INIT_FAILED";
            case 7001: return "ERROR_CODE_VIDEO_FRAME_PROCESSING_FAILED";
            default: return "ERROR_CODE_UNKNOWN_" + code;
        }
    }
}
